                           // 2.3.2（修复 · 门面漏 API）: UMD 门面 `api`（= 浏览器里的 `window.NetsGame`）
                           //    补上 `viewGrid/viewIsActive/viewEnterAt/viewEnterUid/viewExit/viewBackToAc/getViewState`。
