                           //    金标 38303 行逐字一致（纯隔离改动，行为零变化）。新增闸门 data-isolation-verify。
                           // 2.2.15（内部重构 P4-⑤ · 行为零变化）: AC 侧"虚空退出 / ∞ 无限退出"两条
