                           // 2.2.9（内部重构 P4-① · 行为零变化）: 把 AC 侧的**跨视图循环门（viaZeroB）**
                           //    判定并入唯一出界语义 `_resolveLeave`（仅 mover==='ac'，返回 kind:'cyclicCross'
