      interactDirs: ['d', 'a', 's', 'w'], interactExit: true, pushOneMB: true,
      oneWayTwin: true, twinPref: 'current', markBy: 'residence',
      winSpace: WIN_SPACE,     /* 2.4.22：通关空间（默认 50，与内置冒险一致）；null = 没有通关条件 */
      rootSpace: ROOT_SPACE    /* 2.4.22：根空间 = 初始那一个（默认 1，与内置冒险一致） */
