        //        再撞上 `_pickTwinEntry` 的 live 分支（live 有 2 只、且都不在 AC 当前网格 ⇒ 返回 null）
        //        ⇒ **该标号所有 1MB 盒一律进不去**（审计实测 M-E / M-F 两组）✗
        //      为什么现在能放心做：现有 `data/` 每个 MLE 标号本来就恰好 1 只 0B ⇒ 永不触发翻转；
        //        审计用变体引擎实测过 **69 条金标 / 64440 步零差异**，本次改动后金标也逐字复验 ✓
        //      TLE **不参与**（规格 3(1)：TLE 允许同标号多只 0B，每只各自是独立实例）✓
        //      ⚠ **MLE 只做"同一张网格内"的去重，不做跨网格扫描** ——
