      //    旧层在物化期间仍挂在 meta.layers 上，于是"0B 唯一性"看得见"待保留的 0B UKE 盒"，
      //    同标号模板卡按规则生成 1MB（与 _refreshTLE 的次序一致）——
      var fresh = this._buildGrid(g.spaceId, meta.templateCells, 'layer', meta.layerSeq++);
