    if (!view) return false;
    // 仅本次调用新建的层视为 created（复用活跃层时不得误销毁）
    var created = (meta.type === 'TLE' && meta.layers.length > layersBefore) ? view : null;
    var ok = !!this._resolveLanding(view, meta, dir, twinEntry);
